args.sparql:
SELECT ?film ?filmLabel ?dir ?dirLabel ?bdate WHERE {
  VALUES ?film { dbr:Charlie_Chan_in_Honolulu dbr:Lianna }
  ?film (dbo:director|dbp:director) ?dir .
  ?dir (dbo:birthDate|dbp:birthDate) ?bdate .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?dir rdfs:label ?dirLabel . FILTER(lang(?dirLabel) = "en") }
}
ORDER BY DESC(?bdate)
LIMIT 1

